    float rated_voltage;
    float rated_current;
    float rated_torque;
    float max_velocity;
    float max_torque;
    float gearbox_ratio;
    uint16_t encoder_resolution;
    float kp, ki, kd;
    uint8_t protocol;
    uint32_t can_id;
    uint32_t baudrate;
